"""Singhasan's private correspondence and moderated reader responses."""
def responses(c,icon):
    if not c['number']:return ''
    return f'''<section class="poem-engagement" data-poem-engagement="{c['number']}" aria-labelledby="responses-heading" lang="en"><h2 id="responses-heading">After the poem</h2><button class="poem-heart response-heart" type="button" data-like aria-label="Like this poem" aria-pressed="false" disabled>{icon('heart')}<span data-like-label>Like</span><span data-like-count hidden></span></button><span class="like-status" data-like-status role="status"></span><p class="service-note" data-service-note>Likes and comments are unavailable here. You can still write privately.</p><details><summary><span class="response-chevron" aria-hidden="true"></span><span>Comments</span></summary><div class="comments-panel"><p class="comments-intro">A few words about what stayed with you. Comments appear after editorial review.</p><div data-comments-list></div><button type="button" data-comments-more hidden>More comments</button><form><fieldset disabled><legend class="sr-only">Leave a comment</legend><label>Your public name<input name="name" autocomplete="name" maxlength="80" required></label><label>Your comment<textarea name="message" maxlength="2000" placeholder="What did this poem bring to mind?" required></textarea></label><label class="comment-consent"><input type="checkbox" name="consent" required><span>I agree that my name and comment may be published after editorial review. I have not included private contact details.</span></label><p class="comments-note">For corrections or a private message, <a href="contact.html?poem=poem-{c['number']}.html">write to the editor</a>. Likes and submissions use an anonymous browser identifier; clearing browser data can reset it.</p><button type="submit">Submit comment for review</button></fieldset><p role="status"></p></form></div></details><a class="private-note-link" href="contact.html?poem=poem-{c['number']}.html">Write privately {icon('next-poetic')}</a></section>'''


def contact_page(icon):
    return f'''<article class="contact-poet" lang="en"><header><p class="eyebrow artistic-label">{icon('footer-contact')}A letter to the poet</p><h1>Contact the poet</h1><p class="contact-intro">A thought that stayed with you. A question about a poem. A word for its writer.</p><p>Write to Pravakar Satapathy through his family. Messages are currently received by Ahimanikya at <a href="mailto:ahimanikya@gmail.com">ahimanikya@gmail.com</a>.</p></header><div class="contact-layout"><form class="reader-message" data-feedback="private"><fieldset data-contact-fields disabled><h2>Your private message</h2><label>Your name<input name="name" autocomplete="name" maxlength="120" required></label><label>Your email<input type="email" name="email" autocomplete="email" maxlength="254" required></label><label>About<select name="reason"><option value="note">A note to the poet</option><option value="correction">A correction in the book</option></select></label><input type="hidden" name="poem"><label>Your message<textarea name="message" rows="7" maxlength="5000" required></textarea></label><p class="small muted">This opens a draft in your email app. Review it there and choose Send. Your message is private.</p><button type="submit">Open email draft</button><p role="status" aria-live="polite"></p></fieldset><noscript>Please use the email link above to write to the poet.</noscript></form><aside><img src="assets/writers/41-earth-voice-v1.png" width="1086" height="1448" alt="Portrait of Pravakar Satapathy" loading="lazy"><h2 lang="or">ପ୍ରଭାକର ଶତପଥୀ</h2><p>Poet of <i>Singhasan</i></p><a href="author.html">About the poet {icon('next-poetic')}</a></aside></div></article>'''
